const imgProduct = "https://www.figma.com/api/mcp/asset/9d2799a2-f65a-48ed-b1bf-6508d4070baa.png";

type CardHeadingProps = {
  className?: string;
  type?: "Default";
};

function CardHeading({ className, type = "Default" }: CardHeadingProps) {
  return (
    <div className={className || "content-stretch flex items-center min-h-[16px] py-[var(--alias\\/space\\/200,8px)] relative w-[176px]"} data-node-id="40002109:25293">
      <p className="[text-box-edge:cap_alphabetic] [text-box-trim:trim-both] [word-break:break-word] flex-[1_0_0] font-[family-name:var(--brand\/font\/family\/body,'Futura_Round:medium')] font-[var(--brand\/font\/weight\/bold,normal)] leading-[var(--brand\/font\/lineheight\/400,16px)] min-w-px relative text-[color:var(--alias\/color\/text\/default,#191919)] text-[length:var(--brand\/font\/size\/350,14px)] uppercase" data-node-id="40002109:25291">
        Product Name
      </p>
    </div>
  );
}

type ProductCardProps = {
  className?: string;
  size?: "Desktop";
  state?: "Default";
  type?: "Home";
  unavailableComingSoon?: "False";
};

