describe('ZimmProductCard — VARIATION_CONFIG drives composed-child props (a sample, not exhaustive — full matrix is Media/Content’s own test responsibility)', () => {
  test('home never renders the bag, attributes row or size chips', () => {
    wrap(<ZimmProductCard {...buildCardProps('home')} currentPrice="$100.00" />);
    expect(screen.queryByRole('button', { name: 'Add to bag' })).not.toBeInTheDocument();
    expect(document.querySelector('[data-card-slot="sizeChips"]')).not.toBeInTheDocument();
  });

  test('wishlist renders the colour/size attributes row', () => {
    wrap(<ZimmProductCard {...buildCardProps('wishlist')} currentPrice="$100.00" />);
    expect(screen.getByTestId('card-content-attributes')).toBeInTheDocument();
  });

  test('plp out-of-stock renders a disabled bag and a notify-me CTA', () => {
    const onNotifyMe = vi.fn();
    wrap(<ZimmProductCard {...buildCardProps('plp')} isUnavailable onNotifyMe={onNotifyMe} />);
    expect(screen.getByRole('button', { name: 'Add to bag' })).toBeDisabled();
    // Fix C: the organism's own recipe hover-gates this button via `[data-card-slot="notifyMe"]`
    // (see zimmProductCard.css.ts docblock point 4) — needs the real attribute present on the
    // real composed tree, not just Content's own isolated test coverage of the same element.
    expect(screen.getByRole('button', { name: 'Notify me' })).toHaveAttribute('data-card-slot', 'notifyMe');
  });

  /**
   * Fix G (full-sweep follow-up visual audit): `bagHiddenOnMobile` is computed in index.tsx from
   * TWO VARIATION_CONFIG fields (`hideBagOnMobile` — PLP's unconditional rule — and
   * `hideBagOnMobileWhenUnavailable` — Wishlist's narrower, stock-status-dependent one) plus
   * `isUnavailable`. Reading it back off `capturedOrganismStyleProps` (populated by this file's
   * own `useMultiStyleConfig` mock — see that mock's own comment) is what actually proves index.tsx
   * combined them correctly; the "real recipe assertions" block below only proves the RECIPE
   * reacts correctly to whatever `hideBagOnMobile` value it's handed, not that index.tsx computed
   * the right one for a given variation x availability combination.
   */
  test.each([
    ['plp', false, true],
    ['plp', true, true],
    ['wishlist', false, false],
    ['wishlist', true, true],
    ['home', false, false],
    ['home', true, false],
  ] as const)(
    'variation=%s, isUnavailable=%s -> hideBagOnMobile=%s passed to the recipe',
    (variation, isUnavailable, expected) => {
      wrap(<ZimmProductCard {...buildCardProps(variation)} isUnavailable={isUnavailable} onNotifyMe={vi.fn()} />);
      expect(capturedOrganismStyleProps.current?.hideBagOnMobile).toBe(expected);
    },
  );

  /**
   * Same capture technique, closing the loop on Fix C's own suppression logic
   * (`hoverHidesPrice`/`hoverRevealsSizeSelector` AND-ed with `!isUnavailable`,
   * `sizeSelectorUnavailable` AND-ed with `isUnavailable`) — previously only ever verified at the
   * recipe-reaction level (a manually-constructed input into `ZimmProductCardRecipe.baseStyle`
   * directly), never proven that index.tsx itself computes that input correctly for a real
   * variation x availability combination.
   */
  test.each([
    ['home', false, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: false }],
    ['home', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: false }],
    ['plp', false, { hoverHidesPrice: true, hoverRevealsSizeSelector: true, sizeSelectorUnavailable: false }],
    ['plp', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: true }],
    ['wishlist', false, { hoverHidesPrice: true, hoverRevealsSizeSelector: true, sizeSelectorUnavailable: false }],
    ['wishlist', true, { hoverHidesPrice: false, hoverRevealsSizeSelector: false, sizeSelectorUnavailable: true }],
  ] as const)(
    'variation=%s, isUnavailable=%s -> the unavailable-suppression trio resolves to %o',
    (variation, isUnavailable, expected) => {
      wrap(<ZimmProductCard {...buildCardProps(variation)} isUnavailable={isUnavailable} onNotifyMe={vi.fn()} />);
      expect(capturedOrganismStyleProps.current?.hoverHidesPrice).toBe(expected.hoverHidesPrice);
      expect(capturedOrganismStyleProps.current?.hoverRevealsSizeSelector).toBe(expected.hoverRevealsSizeSelector);
      expect(capturedOrganismStyleProps.current?.sizeSelectorUnavailable).toBe(expected.sizeSelectorUnavailable);
    },
  );
});

