40	export type ZimmProductCardMediaProps = {
41	  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
42	  primaryImage: ZimmProductCardMediaImage;
43	  /**
44	   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
45	   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
46	   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
47	   * a hover-swap of just the first two would be a second, inconsistent way to see the same
48	   * content. Has no effect unless `swapOnHover` is also true.
49	   */
