59	  /**
60	   * Enables the desktop prev/next arrows. The touch slide-indicator is independent of this flag
61	   * (per the Figma "Image Group" spec, the touch variant has no separate "controls off" state)
62	   * — it renders whenever there is more than one image to page through, regardless of this prop.
63	   */
64	  showControls: boolean;
65	  /**
66	   * Merchandiser-configured badge label (e.g. "Runway", "Exclusive") — SFCC-236's Figma "Tag"
67	   * overlay, top-left of the image. Renders only when non-empty; a blank/whitespace-only value
68	   * behaves identically to omitting the prop, same guard shape as `removeLabel` below. Which
69	   * variations actually show a badge (PLP/Wishlist yes, Home no) is the organism's job via its
70	   * `VARIATION_CONFIG` — this component only renders what it's given.
71	   */
72	  badge?: string;
73	  /** Wishlist-only remove action. Rendered only when paired with a usable `removeLabel`. */
74	  onRemove?: () => void;
