const root = document.querySelector('[data-testid="product-card"]');
const media = document.querySelector('[data-card-slot="media"]');
const badge = document.querySelector('[data-card-slot="badge"]');
const close = document.querySelector('[data-card-slot="close"]');
const badgeRect = badge?.getBoundingClientRect();
const closeRect = close?.getBoundingClientRect();
JSON.stringify({
  rootWidth: root?.getBoundingClientRect().width,
  mediaWidth: media?.getBoundingClientRect().width,
  badgeRect: badgeRect ? {left: badgeRect.left, right: badgeRect.right, width: badgeRect.width} : null,
  closeRect: closeRect ? {left: closeRect.left, right: closeRect.right, width: closeRect.width} : null,
  overlap: badgeRect && closeRect ? badgeRect.right > closeRect.left : null,
}, null, 2);

