// Root is still forced to 179px from the previous check. Sweep a few real badge names
// (all confirmed examples from the Jira ticket text: Runway, Campaign, Exclusive, Online
// Exclusive, VIC Exclusive) through the actual rendered badge element and re-measure each
// against the real close-button position, to find where the line actually is.
const badgeEl = document.querySelector('[data-card-slot="badge"] span, [data-card-slot="badge"] > *');
const closeRect = document.querySelector('[data-card-slot="close"]').getBoundingClientRect();
const names = ['Runway', 'Campaign', 'Exclusive', 'VIC Exclusive', 'Online Exclusive'];
const results = names.map((name) => {
  badgeEl.textContent = name;
  const r = document.querySelector('[data-card-slot="badge"]').getBoundingClientRect();
  return { name, badgeRight: Math.round(r.right * 10) / 10, closeLeft: Math.round(closeRect.left * 10) / 10, overlapPx: Math.round((r.right - closeRect.left) * 10) / 10 };
});
JSON.stringify(results, null, 2);

