// Previous measurement compared the PADDED WRAPPER boxes (badge div's paddingInline: 24px on
// both sides, close button's full 48px tap-target) — not the actual visible ink. Re-measuring
// the real visible content: the text span itself, and the icon/svg inside the close button.
const badgeWrapper = document.querySelector('[data-card-slot="badge"]');
const badgeTextEl = badgeWrapper.querySelector('span') || badgeWrapper.firstElementChild;
const closeButton = document.querySelector('[data-card-slot="close"]');
const closeIcon = closeButton.querySelector('svg, path') || closeButton.firstElementChild;

const badgeWrapperRect = badgeWrapper.getBoundingClientRect();
const badgeTextRect = badgeTextEl.getBoundingClientRect();
const closeButtonRect = closeButton.getBoundingClientRect();
const closeIconRect = closeIcon ? closeIcon.getBoundingClientRect() : null;

JSON.stringify({
  badgeWrapperRight: badgeWrapperRect.right,
  badgeVisibleTextRight: badgeTextRect.right,
  closeButtonLeft: closeButtonRect.left,
  closeVisibleIconLeft: closeIconRect ? closeIconRect.left : 'no icon element found',
  realVisualGap: closeIconRect ? closeIconRect.left - badgeTextRect.right : null,
}, null, 2);

